import React from "react";
import Sidebar from "./sidebar";

const Layout = ({ children }) => (
  <div style={{ display: "flex" }}>
    <Sidebar />
    <div style={{ flex: 1 }}>
      {children}
    </div>
  </div>
);

export default Layout;
